    private void btnLoginActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnLoginActionPerformed
        // TODO add your handling code here:                                         
        // Mengambil teks dari kolom input (jTextField1 dan jPasswordField1)
        String username = jTextField1.getText();
        String password = new String(jPasswordField1.getPassword());

        // Mengecek kecocokan username dan password
        if (username.equals("admin") && password.equals("12345")) {
            javax.swing.JOptionPane.showMessageDialog(this, "Login Berhasil!");

            // Contoh jika ingin pindah ke form lain (hapus tanda // jika sudah ada FormMenu)
            // new FormMenu().setVisible(true);
            // this.dispose();
        } else {
            javax.swing.JOptionPane.showMessageDialog(this, "Username atau Password salah!", "Login Gagal", javax.swing.JOptionPane.ERROR_MESSAGE);

            // Mengosongkan password dan mengarahkan kursor ke kolom username
            jPasswordField1.setText("");
            jTextField1.requestFocus();
        }
    }//GEN-LAST:event_btnLoginActionPerformed

